if (!in_array($page, ['arsip', 'laporan', 'retensi', 'detail', 'berita', 'notifikasi', 'aktivitas'], true)) { http_response_code(404); exit('Konten tidak tersedia.'); }
if ($page === 'arsip') {
    $q = trim((string) ($_GET['q'] ?? ''));
    $unitId = (int) ($_GET['unit_id'] ?? 0);
