if ($page === 'notifikasi') { $items = $pdo->query('SELECT jenis_notifikasi,tanggal_notifikasi,read_at FROM notifikasi ORDER BY tanggal_notifikasi DESC LIMIT 100')->fetchAll(); ?>
<section class="panel"><div class="archive-results-heading"><div><h2>NOTIFIKASI</h2><p>Daftar notifikasi read-only.</p></div></div><div class="table-wrap archive-results"><table><thead><tr><th>Jenis Notifikasi</th><th>Tanggal</th><th>Status</th></tr></thead><tbody><?php foreach ($items as $item): ?><tr><td><?= e($item['jenis_notifikasi']) ?></td><td><?= e($item['tanggal_notifikasi']) ?></td><td><?= $item['read_at'] === null ? 'Belum dibaca' : 'Sudah dibaca' ?></td></tr><?php endforeach; ?><?php if (!$items): ?><tr><td colspan="3">Belum ada notifikasi.</td></tr><?php endif; ?></tbody></table></div></section>
<?php exit; }
if ($page === 'aktivitas') { $items = $pdo->query("SELECT l.aktivitas,l.keterangan,l.created_at,COALESCE(u.nama_lengkap,'Sistem') nama_lengkap FROM log_aktivitas l LEFT JOIN users u ON u.user_id=l.user_id ORDER BY l.created_at DESC LIMIT 100")->fetchAll(); ?>
<section class="panel"><div class="archive-results-heading"><div><h2>LOG AKTIVITAS</h2><p>Aktivitas terbaru sistem.</p></div></div><div class="table-wrap archive-results"><table><thead><tr><th>User</th><th>Aktivitas</th><th>Keterangan</th><th>Waktu</th></tr></thead><tbody><?php foreach ($items as $item): ?><tr><td><?= e($item['nama_lengkap']) ?></td><td><?= e($item['aktivitas']) ?></td><td><?= e($item['keterangan'] ?? '-') ?></td><td><?= e($item['created_at']) ?></td></tr><?php endforeach; ?><?php if (!$items): ?><tr><td colspan="4">Belum ada log aktivitas.</td></tr><?php endif; ?></tbody></table></div></section>
