s $file): ?><article><i class="material-symbols-outlined"><?= str_starts_with((string) $file['mime_type'], 'image/') ? 'image' : 'picture_as_pdf' ?></i><div><b><?= e($file['nama_file']) ?></b><small><?= e($file['mime_type']) ?></small></div><button type="button" class="spa-preview" data-file="<?= (int) $file['file_id'] ?>" data-name="<?= e($file['nama_file']) ?>">Preview</button><a class="spa-download" href="download-arsip.php?id=<?= (int) $file['file_id'] ?>">Download</a></article><?php endforeach; ?><?php if (!$files): ?><p>Tidak ada file dokumen yang tersedia.</p><?php endif; ?></div></section><div class="spa-preview-panel" hidden><div class="spa-preview-shell"><header><div><b>Preview Dokumen</b><small class="spa-preview-name"></small></div><button type="button" class="spa-preview-close">Tutup</button></header><div class="spa-preview-body"><iframe title="Preview dokumen"></iframe><div class="spa-preview-fallback" hidden><p class="empty-state">Dokumen tidak dapat ditampilkan.</p><a class="spa-download" href="#">Download Dokumen</a></div></div></div></div></div>
